import { useRef } from 'react';

import {
  StyledSliderRange,
  StyledSliderRoot,
  StyledSliderThumb,
  StyledSliderTrack,
} from './CustomSlider.styles';

type CustomSliderType = 'range' | 'fixedRange' | 'slider';
type CustomSliderVisualMode = 'default' | 'inputOnly';

export interface CustomSliderProps {
  type?: CustomSliderType;
  min: number;
  max: number;
  maxInput: number;
  value: number[];
  callback: (values: number[]) => void;
  onValueCommit?: (values: number[]) => void;
  onDraggingChange?: (dragging: boolean) => void;
  step?: number;
  visualMode?: CustomSliderVisualMode;
  dataTestId?: string;
  thumbAriaLabel?: string;
}

export const CustomSlider = ({
  type,
  min,
  max,
  maxInput,
  value,
  callback,
  onValueCommit,
  onDraggingChange,
  step,
  visualMode,
  dataTestId,
  thumbAriaLabel,
}: CustomSliderProps): JSX.Element => {
  const sliderRootRef = useRef(null);
  const isDraggingRef = useRef(false);

  const shouldRenderRange = type !== 'slider';
  const firstThumbVisible = type === 'range';
  const firstThumbAriaLabel =
    type === 'slider' && thumbAriaLabel ? thumbAriaLabel : 'first-value';

  const percentage = ((maxInput + 1) / (max + 1)) * 100 + '%';

  const setDragging = (next: boolean) => {
    if (isDraggingRef.current === next) return;

    isDraggingRef.current = next;
    onDraggingChange?.(next);
  };

  return (
    <StyledSliderRoot
      ref={sliderRootRef}
      $visualMode={visualMode ?? 'default'}
      min={min}
      max={max}
      step={step ?? 1}
      value={value}
      onValueChange={callback}
      onValueCommit={(vals) => {
        if (onValueCommit) {
          onValueCommit(vals);
        } else {
          callback(vals);
        }
        setDragging(false);
      }}
      data-testid={dataTestId}
      onPointerDown={() => {
        setDragging(true);
      }}
      onPointerUp={() => setDragging(false)}
      onPointerCancel={() => setDragging(false)}
      onLostPointerCapture={() => setDragging(false)}
    >
      <StyledSliderTrack
        style={{
          background: `linear-gradient(to right, #b4cee9 0 ${percentage}, #ededed 0)`,
        }}
        data-testid={dataTestId ? `${dataTestId}-track` : undefined}
        $visualMode={visualMode ?? 'default'}
      >
        {shouldRenderRange && <StyledSliderRange />}
      </StyledSliderTrack>
      <StyledSliderThumb
        $visible={firstThumbVisible}
        aria-label={firstThumbAriaLabel}
        $visualMode={visualMode ?? 'default'}
      />
      <StyledSliderThumb
        $visible
        aria-label={thumbAriaLabel ?? 'last-value'}
        $visualMode={visualMode ?? 'default'}
      />
    </StyledSliderRoot>
  );
};
